using namespace std;

class Solution {
    static constexpr int MOD = 1'000'000'007;
    long long modPow(long long b, long long exp) {
        long long res = 1;
        while (exp > 0) {
            if (exp & 1) res = (res * b) % MOD;
            b = (b * b) % MOD;
            exp >>= 1;
        }
        return res;
    }
public:
    vector<int> queryConversions(vector<vector<int>>& conversions, vector<vector<int>>& queries) {
        int n = conversions.size() + 1;
        vector<long long> units(n, 0);
        units[0] = 1;
        vector<vector<pair<int, int>>> graph(n);
        for (const auto& c : conversions) {
            graph[c[0]].push_back({c[1], c[2]});
        }
        queue<int> q;
        q.push(0);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (const auto& [v, factor] : graph[u]) {
                units[v] = (units[u] * factor) % MOD;
                q.push(v);
            }
        }
        vector<int> ans;
        for (const auto& qry : queries) {
            int u = qry[0], v = qry[1];
            long long inv = modPow(units[u], MOD - 2);
            ans.push_back((units[v] * inv) % MOD);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;
    public int[] queryConversions(int[][] conversions, int[][] queries) {
        int n = conversions.length + 1;
        long[] units = new long[n];
        units[0] = 1;
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] c : conversions) {
            graph[c[0]].add(new int[]{c[1], c[2]});
        }
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(0);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int[] edge : graph[u]) {
                int v = edge[0], factor = edge[1];
                units[v] = (units[u] * factor) % MOD;
                q.add(v);
            }
        }
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int u = queries[i][0], v = queries[i][1];
            long inv = modPow(units[u], MOD - 2);
            ans[i] = (int) ((units[v] * inv) % MOD);
        }
        return ans;
    }
    private long modPow(long b, long exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * b) % MOD;
            b = (b * b) % MOD;
            exp >>= 1;
        }
        return res;
    }
}

var queryConversions = function(conversions, queries) {
    const MOD = 1000000007n;
    const n = conversions.length + 1;
    const units = new Array(n).fill(0n);
    units[0] = 1n;
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v, factor] of conversions) {
        graph[u].push([v, BigInt(factor)]);
    }
    const q = [0];
    while (q.length > 0) {
        const u = q.shift();
        for (const [v, factor] of graph[u]) {
            units[v] = (units[u] * factor) % MOD;
            q.push(v);
        }
    }
    const modPow = (b, exp) => {
        let res = 1n;
        while (exp > 0n) {
            if (exp & 1n) res = (res * b) % MOD;
            b = (b * b) % MOD;
            exp >>= 1n;
        }
        return res;
    };
    return queries.map(([u, v]) => {
        const inv = modPow(units[u], MOD - 2n);
        return Number((units[v] * inv) % MOD);
    });
};
